def build_content(spec, drop_facts=(), add_facts=None, drop_claims=(), add_claims=None,
                  drop_objects=False, empty=False):
    if empty:
        return {}
    facts = {p: v for p, v in spec["facts"].items() if p not in drop_facts}
    facts.update(add_facts or {})
    claims = {c: s for c, s in spec["claims"].items() if c not in drop_claims}
    claims.update(add_claims or {})
    return {
        "facts": [{"fact_path": p, "value": v} for p, v in facts.items()],
        "claims": [{"claim_type": c, "statement": s} for c, s in claims.items()],
        "evidence": spec["evidence"],
        "objects": [] if drop_objects else spec["objects"],
    }


def build_wrong_source(spec):
    content = build_content(spec)
    wrong = dict(content["evidence"][0])
    wrong["source_role"] = "company_style_only"
    wrong["locator"] = syn("合成错误来源登记：公司风格材料不得准入本项目主张")
    content["evidence"] = [wrong] + content["evidence"][1:]
    return content


def inactive_content(spec, trigger, record, decided_claim):
    return {
        "facts": [
            {"fact_path": record, "value": syn("附录适用性决定记录：评估为不适用")},
            {"fact_path": trigger, "value": "false"},
        ],
        "claims": [
            {"claim_type": decided_claim, "statement": syn("附录适用性已由实际评估决定（不适用）")},
        ],
        "evidence": spec["evidence"],
        "objects": [para("附录适用性决定承载段：不适用时不含表格")],
    }


FIXTURES = []
EXPECTATIONS = []


def add(fixture_id, kind, content, expected, supplied_passed=None, supplied_qc=None):
    stem = fixture_id.split(":")[2]
    parts = stem.split("-")
    node_id = "v2_n_" + "_".join(parts[1:])
    FIXTURES.append({
        "fixture_id": fixture_id,
        "chapter_contract_id": f"contract:{stem}:v2",
        "fixture_kind": kind,
        "content": content,
        "supplied_passed": supplied_passed,
        "supplied_qc_verdict": supplied_qc,
    })
    EXPECTATIONS.append((fixture_id, node_id, expected))


for node_id in NODE_IDS:
    spec = SPECS[node_id]
    slug = node_id.replace("_", "-")
    prefix = f"fixture:batch8:{slug}"
    extra_kwargs = {}
    if node_id == "v2_n_15":
        extra_kwargs = {
            "supplied_passed": False,
            "supplied_qc": syn("合成自评 fail：确定性检查忽略该自评，不改变机械检查结果"),
        }
    add(f"{prefix}:positive", "positive", build_content(spec),
        {"kind": "positive"}, **extra_kwargs)
    if node_id in ("v2_n_16_x1", "v2_n_16_x2"):
        stem = "ecog" if node_id.endswith("x1") else "nyha"
        content = inactive_content(
            spec, f"appendix.{stem}_assessment_applicable",
            f"appendix.{stem}_applicability_decision_record",
            f"appendix.{stem}_applicability_decided")
        add(f"{prefix}:conditional-inactive", "positive", content, {"kind": "positive"})
    missing_kind = MISSING[node_id]
    mode, target = spec["missing"]
    if mode == "dropped_fact":
        add(f"{prefix}:missing-control", "missing_control", build_content(spec, drop_facts=[target]),
            {"kind": "negative", "codes": {"missing_required_fact"}})
    else:
        add(f"{prefix}:missing-claim", "missing_claim", build_content(spec, drop_claims=[target]),
            {"kind": "negative", "codes": {"missing_required_claim"}})
    add(f"{prefix}:wrong-source", "wrong_source", build_wrong_source(spec),
        {"kind": "negative", "codes": {"wrong_source_role"}})
    add(f"{prefix}:skeleton", "skeleton", {}, {"kind": "negative", "codes": {"skeleton_content"}})
    suffix, changes, expected_codes = spec["named"]
    add(f"{prefix}:{suffix}", missing_kind, build_content(
        spec,
        drop_facts=changes.get("drop_facts", ()),
        add_facts=changes.get("add_facts"),
        drop_claims=changes.get("drop_claims", ()),
        add_claims=changes.get("add_claims"),
        drop_objects=changes.get("drop_objects", False),
    ), {"kind": "negative", "codes": set(expected_codes)})
    for suffix, changes, expected_codes in spec.get("extras", ()):
        add(f"{prefix}:{suffix}", missing_kind, build_content(
            spec,
            drop_facts=changes.get("drop_facts", ()),
            add_facts=changes.get("add_facts"),
            drop_claims=changes.get("drop_claims", ()),
            add_claims=changes.get("add_claims"),
            drop_objects=changes.get("drop_objects", False),
        ), {"kind": "negative", "codes": set(expected_codes)})

failures = []
for fixture_id, node_id, expected in EXPECTATIONS:
    contract = ChapterContractV2.model_validate(
        json.loads((TPL / "chapter_contracts" / f"{node_id}.json").read_text(encoding="utf-8")))
    fixture = next(f for f in FIXTURES if f["fixture_id"] == fixture_id)
    payload = ChapterContentPayload.model_validate(fixture["content"])
    result = evaluate_chapter_content(
        contract, payload, subject_id=fixture_id,
        supplied_passed=fixture["supplied_passed"],
        supplied_qc_verdict=fixture["supplied_qc_verdict"])
    codes = {f.code for f in result.findings if f.severity == "error"}
    if expected["kind"] == "positive":
        if not result.passed:
            failures.append((fixture_id, "positive failed", sorted(codes)))
    else:
        missing_codes = set(expected["codes"]) - codes
        if result.passed or missing_codes:
            failures.append((fixture_id, "negative expectation", sorted(codes), sorted(missing_codes)))
    for fact in payload.facts:
        if fact.value not in (None, "true", "false") and "合成" not in fact.value:
            failures.append((fixture_id, "missing synthetic marker", fact.fact_path))
    for claim in payload.claims:
        if claim.statement is not None and "合成" not in claim.statement:
            failures.append((fixture_id, "missing synthetic marker", claim.claim_type))

if failures:
    print("PRE-VALIDATION FAILED; file not written")
    for item in failures[:20]:
        print(" ", item)
    raise SystemExit(1)

fact_vocabulary, claim_vocabulary = set(), set()
for node_id in NODE_IDS:
    contract = ChapterContractV2.model_validate(
        json.loads((TPL / "chapter_contracts" / f"{node_id}.json").read_text(encoding="utf-8")))
    substantive = contract.substantive_content
    fact_vocabulary.update(item.fact_path for item in substantive.fact_requirements)
